{
  "implementation": "import math

def solve(case):
    matrix = case['matrix']
    # Validate nonempty rectangular matrix
    if not matrix or not all(isinstance(row, list) for row in matrix):
        raise ValueError('Invalid matrix')
    n_rows = len(matrix)
    n_cols = len(matrix[0]) if matrix else 0
    if n_rows == 0 or n_cols == 0:
        raise ValueError('Empty matrix')
    if not all(len(row) == n_cols for row in matrix):
        raise ValueError('Irregular matrix')

    # Compute document frequency per column
    doc_freq = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                doc_freq[j] += 1

    # Compute IDF
    idf = []
    for df in doc_freq:
        # log(1 + n_rows / (1 + df))
        idf_val = math.log(1.0 + n_rows / (1.0 + df))
        idf.append(round(idf_val, 6))

    # Compute weighted matrix and row degrees
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = []
        row_sum = 0.0
        for j, val in enumerate(row):
            w = val * idf[j]
            weighted_row.append(round(w, 6))
            row_sum += w
        weighted_matrix.append(weighted_row)
        row_degree.append(round(row_sum, 6))

    return {
        'idf': idf,
        'row_degree': row_degree,
        'weighted_matrix': weighted_matrix
    }"
}
